using System;
using System.Collections;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;
public sealed class DownInterceptTests : MonoBehaviour {
    public static bool UseAI;static bool booted;static KeyCode pressed=KeyCode.None;
    public static bool ReadKey(KeyCode k){return false;}public static bool ReadDown(KeyCode k){return k==pressed;}
    Component fan,zhao,manager;Type pt;Rigidbody2D ball;float scale;int checks,failures;static readonly HashSet<string> hits=new HashSet<string>();
    const BindingFlags IP=BindingFlags.Instance|BindingFlags.NonPublic,SP=BindingFlags.Static|BindingFlags.NonPublic;
    public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","down-test.ini");var o=new GameObject("DownInterceptTests");DontDestroyOnLoad(o);o.AddComponent<DownInterceptTests>();}
    public static void Contacted(Collision2D c){if(c!=null&&c.collider!=null){Component p=c.collider.transform.root;hits.Add(p.name);}}
    void Check(bool ok,string text){checks++;if(!ok)failures++;Debug.Log("ABILITY "+(ok?"PASS ":"FAIL ")+text);}
    Rigidbody2D Body(Component p){return (Rigidbody2D)pt.GetField("rb").GetValue(p);}
    object Field(DownIntercept p,string n){return typeof(DownIntercept).GetField(n,IP).GetValue(p);}
    float Floor(DownIntercept p){return (float)typeof(DownIntercept).GetMethod("Floor",IP).Invoke(p,null);}
    void Move(Component p,Vector2 at){p.transform.position+=(Vector3)(at-Body(p).position);foreach(var r in p.GetComponentsInChildren<Rigidbody2D>()){r.velocity=Vector2.zero;r.angularVelocity=0;}Physics2D.SyncTransforms();}
    float Error(Component p){float e=0;foreach(var j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)e=Mathf.Max(e,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return e;}
    bool Glow(Component p){if(AbilityMode.Enabled){var b=p.GetComponent<BuildPlayer>();return b!=null&&((float[])typeof(BuildPlayer).GetField("effects",IP).GetValue(b))[9]>=0;}var s=p.GetComponent<PlayerSkills>();return s!=null&&((float[])typeof(PlayerSkills).GetField("effects",IP).GetValue(s))[9]>=0;}
    IEnumerator Scene(int mode){pressed=KeyCode.None;Time.timeScale=1;UseAI=false;ControlBindings.ResetDefaults();AbilityMode.Enabled=mode==2;PlayerSkills.Enabled=mode==1;AbilityMode.Reset();if(mode==2){foreach(var b in AbilityMode.Builds){b.Levels[0]=4;b.Levels[1]=4;b.Levels[2]=0;b.Purchased=1<<9;}}
        typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.3f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;Move(fan,new Vector2(-3*scale,Body(fan).position.y));Move(zhao,new Vector2(3*scale,Body(zhao).position.y));ball.position=new Vector2(0,10);ball.gravityScale=0;ball.velocity=Vector2.zero;yield return new WaitForSeconds(.15f);GameAIMod.OnBallReset();}
    void BallAt(Component actor,float height){var d=actor.GetComponent<DownIntercept>();ball.position=new Vector2(Body(actor).position.x+(actor.name=="Fan"?1:-1)*2f*scale,Floor(d)+height);ball.velocity=Vector2.zero;ball.angularVelocity=0;ball.gravityScale=0;Physics2D.SyncTransforms();}
    IEnumerator Manual(int mode,bool isFan){yield return Scene(mode);Component actor=isFan?fan:zhao;var d=actor.GetComponent<DownIntercept>();bool skilled=mode==2||mode==1&&isFan;float head=(float)Field(d,"headHeight"),shin=(float)Field(d,"shinHeight"),limit=skilled?head:shin;
        BallAt(actor,limit-.025f*scale);bool inside=DownIntercept.Eligible(actor,skilled);BallAt(actor,limit+.025f*scale);bool outside=DownIntercept.Eligible(actor,skilled);Check(head>shin&&inside&&!outside&&DownIntercept.HasSkill(actor)==skilled,"initial standing threshold mode="+mode+" actor="+actor.name+" head="+head+" shin="+shin);
        pressed=ControlBindings.Get(isFan,GameControlAction.Down);yield return new WaitForSeconds(.06f);pressed=KeyCode.None;Check((float)Field(d,"lastPress")<0,"outside range rejects down without animation mode="+mode+" actor="+actor.name);
        BallAt(actor,skilled?(head+shin)*.5f:shin*.7f);Vector2 before=ball.position;pressed=ControlBindings.Get(isFan,GameControlAction.Down);yield return new WaitForSeconds(.07f);pressed=KeyCode.None;Check((float)Field(d,"lastPress")>0&&(!skilled||Glow(actor))&&Vector2.Distance(ball.position,before)<.1f*scale,"stationary front ball ground manual action and paid effect mode="+mode+" actor="+actor.name);
    }
    IEnumerator Air(int mode,bool isFan){yield return Scene(mode);Component actor=isFan?fan:zhao;var d=actor.GetComponent<DownIntercept>();bool skilled=mode==2||mode==1&&isFan;float limit=(float)Field(d,skilled?"headHeight":"shinHeight"),floor=Floor(d);Move(actor,Body(actor).position+Vector2.up*1.8f*scale);foreach(var r in actor.GetComponentsInChildren<Rigidbody2D>())r.velocity=Vector2.up;
        ball.position=new Vector2(Body(actor).position.x-(isFan?1:-1)*1.8f*scale,floor+limit*.6f);ball.velocity=Vector2.zero;ball.gravityScale=0;Physics2D.SyncTransforms();float min=0;pressed=ControlBindings.Get(isFan,GameControlAction.Down);
        for(int i=0;i<35;i++){yield return new WaitForFixedUpdate();if(i==3)pressed=KeyCode.None;min=Mathf.Min(min,Body(actor).velocity.y);}Check((float)Field(d,"lastPress")>0&&min<-2f*scale&&Error(actor)<.6f&&(!skilled||Glow(actor)),"rear stationary air manual drops through physics mode="+mode+" actor="+actor.name+" descent="+min);
    }
    IEnumerator RealKick(bool isFan){yield return Scene(0);Component actor=isFan?fan:zhao;float dir=isFan?1:-1;Collider2D leg=actor.transform.Find("R_LowLeg").GetComponent<Collider2D>(),other=actor.transform.Find("L_LowLeg").GetComponent<Collider2D>();Vector2 edge=leg.ClosestPoint((Vector2)leg.transform.position+Vector2.right*dir*2f),edge2=other.ClosestPoint((Vector2)other.transform.position+Vector2.right*dir*2f);if(dir*(edge2.x-edge.x)>0)edge=edge2;ball.position=edge+Vector2.right*dir*(ball.GetComponent<Collider2D>().bounds.extents.x+.012f);ball.velocity=Vector2.right*-dir*.8f;ball.gravityScale=1;Physics2D.SyncTransforms();hits.Clear();pressed=ControlBindings.Get(isFan,GameControlAction.Down);for(int i=0;i<30;i++){yield return new WaitForFixedUpdate();if(i==3)pressed=KeyCode.None;}Check(hits.Contains(actor.name)&&Error(actor)<.6f,"unskilled down uses actual leg/ball collision "+actor.name);}
    IEnumerator Guards(){yield return Scene(2);var d=fan.GetComponent<DownIntercept>();BallAt(fan,(float)Field(d,"headHeight")*.7f);ControlBindings.Set(true,GameControlAction.Down,KeyCode.F);pressed=KeyCode.F;yield return new WaitForSeconds(.06f);pressed=KeyCode.None;Check((float)Field(d,"lastPress")>0&&Glow(fan),"remapped down activates purchased zero-jump intercept");DownIntercept.ResetAll();Time.timeScale=0;pressed=KeyCode.F;yield return null;yield return null;Check((float)Field(d,"lastPress")<0&&!DownIntercept.Eligible(fan,true),"pause and reset suppress manual activation");pressed=KeyCode.None;Time.timeScale=1;}
    IEnumerator Start(){Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=120;AudioListener.volume=0;yield return new WaitForSeconds(.2f);for(int mode=0;mode<3;mode++)foreach(bool actor in new bool[]{true,false}){yield return Manual(mode,actor);yield return Air(mode,actor);}yield return RealKick(true);yield return RealKick(false);yield return Guards();Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
    void Update(){if(Time.realtimeSinceStartup>115){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
}